    id: "palimpseste_architrave_abydos_sethi_ramses",
    civId: "egypte",
    periodId: "nouvel_empire",
    civName: "Égypte : Nouvel Empire",
    century: "XIXe dynastie (v. -1290 à -1250 av. J.-C.)",
